const article = document.getElementById('article');
const p1 = document.getElementById('lead-paragraph');
const p2 = document.getElementById('second-paragraph');
const nav = document.querySelector('nav');
const aside = document.getElementById('sidebar');
const footer = document.querySelector('footer');
return !!article && !!p1 && !!p2 && !!nav && !!aside && !!footer;

const ra = window.__ai4a11yReadAloud;
if (!ra) return false;
const main = document.querySelector('main');
const text = ra.extractReadableText(main);
if (!text.includes('The Search for Water on Mars. Recent rover discoveries')) return false;
if (!text.includes('Key Discoveries. Sedimentary delta deposits in Jezero crater.')) return false;
const chunks = ra.chunk(text);
if (!chunks.length) return false;
if (!chunks.every(c => c.length <= 220)) return false;
return true;

const ra = window.__ai4a11yReadAloud;
if (!ra) return false;
const bodyText = ra.extractReadableText(document.body);
if (bodyText.includes('Astronomy Digest') || bodyText.includes('Main Navigation')) return false;
if (bodyText.includes('Related Publications') || bodyText.includes('sister publication')) return false;
if (bodyText.includes('All rights reserved')) return false;
if (bodyText.includes('decorative text') || bodyText.includes('hidden attribute') || bodyText.includes('display none')) return false;
if (bodyText.includes('Real-time telemetry status')) return false;
if (bodyText.includes('Excellent') || bodyText.includes('Enter comments here')) return false;
return true;

const ra = window.__ai4a11yReadAloud;
if (!ra) return false;
ra.setRate(1.5);
if (ra.settings.rate !== 1.5) return false;
ra.applyPreset('slow');
if (ra.settings.rate !== 0.7) return false;
ra.applyPreset('normal');
if (ra.settings.rate !== 1.0) return false;

const lead = document.getElementById('lead-paragraph');
const range = document.createRange();
range.selectNodeContents(lead);
const sel = window.getSelection();
sel.removeAllRanges();
sel.addRange(range);
ra.speakSelection();
sel.removeAllRanges();

ra.pause();
ra.resume();
ra.stop();
if (ra.speaking || ra.paused || ra.gestureHandler !== null) return false;
return true;

const navLink = document.querySelector('nav a');
if (!navLink) return false;
navLink.focus();
if (document.activeElement !== navLink) return false;
navLink.blur();
return document.documentElement.scrollWidth <= 320;
